function committedFor(sku){const seen=new Set();let count=0;for(const r of demoReservations){if(r.sku!==sku||seen.has(r.id))continue;seen.add(r.id);if(['HELD','READY_FOR_PICKUP','RESERVED'].includes(r.status))count+=Math.max(0,Number(r.qty)||0)}return count}
