function load(){try{const s=JSON.parse(localStorage.getItem(KEY));return s && s.products && s.profiles ? {...initial(),...s}:initial()}catch{return initial()}}
let db=load();
// Non-destructive schema migration for browser demos saved before dimensions were added.
for(const p of db.products){if(p.active===undefined)p.active=p.sku!=='TACJ1436';if(p.imageSlot1===undefined)p.imageSlot1=p.xImage||'';for(let i=2;i<=6;i++)if(p['imageSlot'+i]===undefined)p['imageSlot'+i]='';for(const k of ['length','width','height','committed'])if(p[k]===undefined)p[k]=0;if(p.itemOnline===undefined)p.itemOnline=p.eStatus==='Enabled';if(p.tags===undefined)p.tags='';if(p.variants===undefined)p.variants='Standard';if(p.seoTitle===undefined)p.seoTitle='';if(p.addedBySO===undefined)p.addedBySO=false;if(p.eMinQty===undefined)p.eMinQty=null;if(p.eMaxQty===undefined)p.eMaxQty=null}
for(const perUser of Object.values(db.profiles||{})){for(const layout of Object.values(perUser)){if(Array.isArray(layout.columns)&&!layout.columns.some(c=>['dimensions','length','width','height'].includes(c)))layout.columns.push('dimensions')}}let hideInactive=false;let detailScreen='summary';let user='Alex',slot='0',chosen=null,selected=new Set(),sortKey='sku',sortAsc=true,filterRules=[],filterMode='AND',showIssues=false,selectedOnly=false,search='';
const $=id=>document.getElementById(id);const save=()=>localStorage.setItem(KEY,JSON.stringify(db));
const escapeHtml=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fields=()=>[...baseFields,...db.customFields];const field=id=>fields().find(f=>f.id===id);
function initProfiles(){if(!db.profiles[user])db.profiles[user]={};for(let i=0;i<4;i++)if(!db.profiles[user][i])db.profiles[user][i]={name:i?'Profile '+i:'Default',columns:[...defaultCols],sortKey:'sku',sortAsc:true,filters:[],filterMode:'AND'};save()}
const profile=()=>db.profiles[user][slot];
const colWidth=id=>Math.max(52,Math.min(650,Number(profile().widths?.[id])||({dimensions:152,sku:115,name:235,tags:130,seoTitle:160,committed:98,available:92}[id]||124)));
function saveLayout(){Object.assign(profile(),{sortKey,sortAsc,filters:filterRules,filterMode,hideInactive});save()}
function setProfile(){initProfiles();$('profileSelect').innerHTML=Object.entries(db.profiles[user]).map(([k,v])=>`<option value="${k}" ${k===slot?'selected':''}>${escapeHtml(v.name)}</option>`).join('');const p=profile();sortKey=p.sortKey;sortAsc=p.sortAsc;filterRules=p.filters||[];filterMode=p.filterMode||'AND';hideInactive=!!p.hideInactive;if($('hideInactive'))$('hideInactive').checked=hideInactive;render()}
const product=sku=>db.products.find(p=>p.sku===sku);const value=(p,key)=>key==='committed'?committedFor(p.sku):key==='available'?Number(value(p,'inventory')||0)-Number(value(p,'committed')||0):Object.prototype.hasOwnProperty.call(db.drafts,`${p.sku}|${key}`)?db.drafts[`${p.sku}|${key}`]:p[key];
const missing=p=>!Number(value(p,'cost'))||!value(p,'upc')||(!value(p,'xImage')&&!db.imageAssociations[p.sku])||!value(p,'eId');
function draftCount(){return Object.keys(db.drafts).filter(k=>{const [sku,key]=k.split('|');return product(sku)&&String(db.drafts[k]??'')!==String(product(sku)[key]??'')}).length}
function resetRedundantDrafts(){for(const k of Object.keys(db.drafts)){const [sku,f]=k.split('|');if(product(sku)&&String(db.drafts[k]??'')===String(product(sku)[f]??''))delete db.drafts[k]}}
function change(sku,key,raw){const f=field(key),p=product(sku);if(!f||!f.editable||!p)return;let val=f.kind==='number'?(raw===''?'':Number(raw)):f.kind==='boolean'?raw==='true'||raw===true:String(raw);if(f.kind==='number'&&raw!==''&&!Number.isFinite(val)){toast('Enter a valid number');return}if(f.kind==='number'&&val!==''&&val<0){toast('Negative values are not allowed');return}db.drafts[`${sku}|${key}`]=val;resetRedundantDrafts();save();render()}
function matchesFilter(p,r){const v=String(value(p,r.field)??'').toLowerCase(),q=String(r.value??'').toLowerCase();switch(r.op){case 'contains':return v.includes(q);case 'notcontains':return !v.includes(q);case 'eq':return v===q;case 'neq':return v!==q;case 'empty':return !v;case 'notempty':return !!v;case 'gt':return Number(v)>Number(q);case 'lt':return Number(v)<Number(q);default:return true}}
function visible(){let list=db.products.filter(p=>{const q=search.toLowerCase();return [p.sku,p.name,p.upc,p.description,p.brand,p.supplierSku].some(x=>String(x||'').toLowerCase().includes(q))});if(hideInactive)list=list.filter(p=>value(p,'active')!==false);if(showIssues)list=list.filter(missing);if(selectedOnly)list=list.filter(p=>selected.has(p.sku));if(filterRules.length)list=list.filter(p=>filterMode==='AND'?filterRules.every(r=>matchesFilter(p,r)):filterRules.some(r=>matchesFilter(p,r)));list.sort((a,b)=>{const va=value(a,sortKey),vb=value(b,sortKey);const res=typeof va==='number'&&typeof vb==='number'?va-vb:String(va??'').localeCompare(String(vb??''),undefined,{numeric:true});return sortAsc?res:-res});return list}
function format(v,f){if(v===undefined||v===null||v==='')return '—';if(f.kind==='boolean')return v===true||v==='true'?'Yes':'No';if(f.kind==='number'&&typeof v==='number')return ['price','cost','ePrice','eCompare'].includes(f.id)?'$'+v.toFixed(2):String(v);return String(v)}
function undoButton(sku,key){return `<button type="button" class="undo-cell" data-undo-sku="${escapeHtml(sku)}" data-undo-key="${escapeHtml(key)}" title="Undo this uncommitted change" aria-label="Undo ${escapeHtml(key)} for ${escapeHtml(sku)}">×</button>`}
function undoOne(sku,key){delete db.drafts[`${sku}|${key}`];save();render()}
function inlineControl(p,key,f){const val=value(p,key),dirty=Object.hasOwn(db.drafts,`${p.sku}|${key}`);if(key==='name')return `<button class="name-edit ${dirty?'dimension-dirty':''}" data-name-edit="${escapeHtml(p.sku)}" title="Double-click or press to edit product name">${escapeHtml(val??'')} ${dirty?'✎':''}</button>`;if(key==='category')return `<button class="category-edit ${dirty?'dimension-dirty':''}" data-category-edit="${escapeHtml(p.sku)}" title="Choose a category">${escapeHtml(val??'—')} ▾</button>`;if(f.kind==='boolean')return `<input class="inline-editor ${dirty?'dimension-dirty':''}" type="checkbox" data-key="${key}" data-sku="${escapeHtml(p.sku)}" ${val?'checked':''} aria-label="${escapeHtml(f.name)} for ${escapeHtml(p.sku)}">`;return `${['price','cost','eCompare','ePrice'].includes(key)?'<span class="currency-prefix">$</span>':''}<input class="inline-editor ${dirty?'dimension-dirty':''}" data-key="${key}" data-sku="${escapeHtml(p.sku)}" type="${f.kind==='number'?'number':'text'}" ${f.kind==='number'?'min="0" step="any"':''} value="${escapeHtml(val??'')}" title="${escapeHtml(f.name)} · ${escapeHtml(p.sku)}">`}
function render(){resetRedundantDrafts();const data=visible(),cols=profile().columns.filter(k=>field(k));$('productCount').textContent=`${data.length} of ${db.products.length} products`;$('filterCount').textContent=filterRules.length?`(${filterRules.length})`:'';$('draftBadge').textContent=draftCount();$('selectionCount').textContent=`${selected.size} selected`;$('tableHead').innerHTML=`<tr><th><input id="headSelect" type="checkbox" title="Select visible products"></th>${cols.map(c=>{let f=field(c);return `<th data-sort="${c}" style="width:${colWidth(c)}px;min-width:${colWidth(c)}px;max-width:${colWidth(c)}px" title="Sort by ${escapeHtml(f.name)}">${escapeHtml(f.name)} ${sortKey===c?(sortAsc?'↑':'↓'):''} <span class="resize-handle" data-resize="${c}" title="Drag to resize column"></span></th>`}).join('')}</tr>`;$('tableBody').innerHTML=data.map(p=>`<tr data-sku="${escapeHtml(p.sku)}" class="${chosen===p.sku?'active':''}"><td><input class="select-row" data-sku="${escapeHtml(p.sku)}" type="checkbox" ${selected.has(p.sku)?'checked':''}></td>${cols.map(c=>{let f=field(c),val=value(p,c),dirty=Object.hasOwn(db.drafts,`${p.sku}|${c}`);if(c==='dimensions'){return `<td class="dimension-cell" style="width:${colWidth(c)}px;min-width:${colWidth(c)}px;max-width:${colWidth(c)}px"><div class="dimension-inputs">${['length','width','height'].map(k=>`<label title="${k[0].toUpperCase()+k.slice(1)} in inches"><span>${k[0].toUpperCase()}</span><input type="number" step="any" min="0" aria-label="${k} in inches for ${escapeHtml(p.sku)}" data-dimension="${k}" data-sku="${escapeHtml(p.sku)}" class="${Object.hasOwn(db.drafts,`${p.sku}|${k}`)?'dimension-dirty':''}" value="${escapeHtml(value(p,k)??'')}">${Object.hasOwn(db.drafts,`${p.sku}|${k}`)?undoButton(p.sku,k):''}</label>`).join('')}</div></td>`}return `<td style="width:${colWidth(c)}px;min-width:${colWidth(c)}px;max-width:${colWidth(c)}px" title="${escapeHtml(format(val,f))}" data-edit="${escapeHtml(c)}" data-sku="${escapeHtml(p.sku)}" class="${f.editable?'editable':'readonly-cell'} ${dirty?'dirty':''}">${f.editable?`<div class="edit-wrap">${inlineControl(p,c,f)}${dirty?undoButton(p.sku,c):''}</div>`:escapeHtml(format(val,f))}</td>`}).join('')}</tr>`).join('')||'<tr><td colspan="30" class="empty">No products match your search and filters.</td></tr>';
 document.querySelectorAll('[data-undo-key]').forEach(b=>b.onclick=e=>{e.stopPropagation();undoOne(b.dataset.undoSku,b.dataset.undoKey)});document.querySelectorAll('[data-name-edit]').forEach(b=>b.onclick=e=>{e.stopPropagation();editField(b.dataset.nameEdit,'name')});document.querySelectorAll('[data-category-edit]').forEach(b=>b.onclick=e=>{e.stopPropagation();categoryPicker(b.dataset.categoryEdit)});
 document.querySelectorAll('#tableHead th[data-sort]').forEach(th=>{th.draggable=true;th.ondragstart=e=>{if(e.target.classList.contains('resize-handle')){e.preventDefault();return}e.dataTransfer.setData('text/plain',th.dataset.sort)};th.ondragover=e=>e.preventDefault();th.ondrop=e=>{e.preventDefault();const moved=e.dataTransfer.getData('text/plain'),dest=th.dataset.sort,cols=profile().columns;if(!cols.includes(moved)||moved===dest)return;cols.splice(cols.indexOf(moved),1);cols.splice(cols.indexOf(dest),0,moved);save();render()}});
 document.querySelectorAll('.resize-handle').forEach(handle=>{handle.onpointerdown=e=>{e.preventDefault();e.stopPropagation();const id=handle.dataset.resize,start=e.clientX,old=colWidth(id);const move=ev=>{profile().widths??={};profile().widths[id]=Math.max(52,Math.min(650,old+ev.clientX-start));document.querySelectorAll(`[data-sort="${id}"], td[data-edit="${id}"]`).forEach(el=>{el.style.width=profile().widths[id]+'px';el.style.minWidth=profile().widths[id]+'px';el.style.maxWidth=profile().widths[id]+'px'});if(id==='dimensions')document.querySelectorAll('.dimension-cell').forEach(el=>{el.style.width=profile().widths[id]+'px';el.style.minWidth=profile().widths[id]+'px';el.style.maxWidth=profile().widths[id]+'px'})};const up=()=>{window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',up);save()};window.addEventListener('pointermove',move);window.addEventListener('pointerup',up)}});
 document.querySelectorAll('[data-sort]').forEach(el=>el.onclick=()=>{if(el.dataset.sort==='dimensions')return;const s=el.dataset.sort;sortAsc=sortKey===s?!sortAsc:true;sortKey=s;saveLayout();render()});document.querySelectorAll('.select-row').forEach(el=>el.onchange=()=>{el.checked?selected.add(el.dataset.sku):selected.delete(el.dataset.sku);render()});const hs=$('headSelect');if(hs){hs.checked=data.length>0&&data.every(p=>selected.has(p.sku));hs.onchange=()=>{data.forEach(p=>hs.checked?selected.add(p.sku):selected.delete(p.sku));render()}};
 document.querySelectorAll('#tableBody tr[data-sku]').forEach(el=>el.onclick=e=>{if(e.target.closest('input,button'))return;if(chosen!==el.dataset.sku)detailScreen='summary';chosen=el.dataset.sku;render()});document.querySelectorAll('td[data-edit]').forEach(el=>el.ondblclick=()=>editField(el.dataset.sku,el.dataset.edit));document.querySelectorAll('.inline-editor').forEach(el=>{el.onchange=()=>change(el.dataset.sku,el.dataset.key,el.type==='checkbox'?el.checked:el.value);el.onclick=e=>e.stopPropagation()});document.querySelectorAll('input[data-dimension]').forEach(el=>el.onchange=()=>change(el.dataset.sku,el.dataset.dimension,el.value));if(chosen)details()}
const categoryTree={Games:{'Card Games':['Card Accessories','Deck Boxes','Sleeves'],'Board Games':['Family','Strategy']},Models:{'Model Kits':['Aircraft','Ships','Vehicles'],'Gundam':['HG','MG','RG']},Trains:{'Locomotives':['Steam','Diesel'],'Scenery':['Buildings','Signs']}};
function categoryPicker(sku){const p=product(sku);if(!p)return;const parts=String(value(p,'category')||'').split('/').map(x=>x.trim());const top=Object.keys(categoryTree),prev1=top.includes(parts[0])?parts[0]:top[0];modal('Choose Category',`<p><b>${escapeHtml(sku)}</b> · Categories are selected by hierarchy, like Games / Card Games / Card Accessories.</p><div class="cat-pickers"><label>Category 1<select id="cat1"></select></label><label>Category 2<select id="cat2"></select></label><label>Category 3<select id="cat3"></select></label></div><p class="footnote">Demo taxonomy only. Live category choices will come from X-Series; invalid paths cannot be committed.</p>`,[{text:'Cancel',action:closeModal},{text:'Stage Category',primary:true,action:()=>{change(sku,'category',[$('cat1').value,$('cat2').value,$('cat3').value].filter(Boolean).join(' / '));closeModal()}}]);const setOpts=(el,arr,pick)=>{el.innerHTML=arr.map(v=>`<option ${v===pick?'selected':''}>${escapeHtml(v)}</option>`).join('')};setOpts($('cat1'),top,prev1);const populate2=()=>{const a=Object.keys(categoryTree[$('cat1').value]);setOpts($('cat2'),a,parts[1]);populate3()};const populate3=()=>setOpts($('cat3'),categoryTree[$('cat1').value][$('cat2').value]||[],parts[2]);$('cat1').onchange=populate2;$('cat2').onchange=populate3;populate2()}
function editField(sku,id){const f=field(id),p=product(sku);if(!f||!p)return;if(!f.editable){toast('Read-only: this field is controlled by its source or synchronization policy');return}const current=value(p,id);let input=f.kind==='boolean'?`<select id="editValue"><option value="true" ${current===true?'selected':''}>Yes</option><option value="false" ${current!==true?'selected':''}>No</option></select>`:`<input id="editValue" ${f.kind==='number'?'type="number" step="any" min="0"':''} value="${escapeHtml(current??'')}">`;modal(`Edit ${f.name}`,`<p><strong>${escapeHtml(p.sku)}</strong> · ${escapeHtml(p.name)}</p><div class="formrow"><label>${escapeHtml(f.name)}</label>${input}</div><p class="footnote">Source: ${f.system==='HC'?'Hobby Corner shared custom field':f.system==='X'?'X-Series retail':'E-Series online-only'}. This edit is staged, not sent live.</p>`,[{text:'Cancel',action:closeModal},{text:'Stage Change',primary:true,action:()=>{change(sku,id,$('editValue').value);closeModal()}}]);$('editValue').focus()}
function details(){
 const p=product(chosen);if(!p)return;
 $('detailSku').textContent=p.sku;
 const screenOptions=[['summary','Summary'],['product','Product Details'],['pictures','Picture Details'],['ai','AI Suggestions (Demo)']];
 const selector=`<label class="detail-screen-label">Edit screen <select id="detailScreen">${screenOptions.map(([id,label])=>`<option value="${id}" ${detailScreen===id?'selected':''}>${label}</option>`).join('')}</select></label>`;
 let body='';
 if(detailScreen==='summary'){
  const img=value(p,'imageSlot1')||value(p,'eImage')||db.imageAssociations[p.sku]||'';
  const safeUrl=/^https:\/\//i.test(img)?img:'';
  body=`<div class="product-picture">${safeUrl?`<img src="${escapeHtml(safeUrl)}" alt="Product preview">`:'<div class="missing-img">No linked product image</div>'}</div><h3>${escapeHtml(value(p,'name'))}</h3>`+
  [['SKU',p.sku],['UPC',value(p,'upc')||'Missing'],['X Retail',format(value(p,'price'),field('price'))],['E Online',p.eId?format(value(p,'ePrice'),field('ePrice')):'Not linked'],['Item Online (X)',value(p,'itemOnline')?'Yes':'No'],['On Hand / Held / Available',`${value(p,'inventory')} / ${value(p,'committed')} / ${value(p,'available')}`]].map(([label,val])=>`<div class="detail-row"><label>${escapeHtml(label)}</label><span>${escapeHtml(val)}</span></div>`).join('')+
  `<div class="detail-section"><button id="driveLookup" class="full">Find matching Drive image</button></div>`;
 }else if(detailScreen==='product'){
  const defaultIds=['name','sku','supplier','supplierSku','upc','brand','category','price','cost','tags','description','weight','length','width','height','reorder','restock','itemOnline','seoTitle','eMinQty','eMaxQty','inventory','committed','available','addedBySO',...db.customFields.map(f=>f.id)];const ids=[...(profile().detailOrder||[]).filter(id=>defaultIds.includes(id)),...defaultIds.filter(id=>!(profile().detailOrder||[]).includes(id))];
  body=`<div class="notice">Drag the ☰ handles to reorder details within this profile. Edit individual values here; updates stay staged until Review Changes. Grey values are read-only. SKU is displayed read-only until safe identifier remapping is implemented.</div><div class="detail-edit-list">${ids.map(id=>{const f=field(id);if(!f)return '';const v=value(p,id),dirty=Object.hasOwn(db.drafts,`${p.sku}|${id}`);const editable=f.editable&&id!=='sku';let control=editable?(id==='name'||id==='category'?`<button class="side-edit-name" data-side-modal="${id}">${escapeHtml(String(v??'—'))} ✎</button>`:f.kind==='boolean'?`<input type="checkbox" class="side-edit" data-side-key="${id}" ${v?'checked':''}>`:`<input class="side-edit" data-side-key="${id}" type="${f.kind==='number'?'number':'text'}" value="${escapeHtml(v??'')}" ${f.kind==='number'?'step="any" min="0"':''}>`):`<span class="side-readonly">${escapeHtml(format(v,f))}</span>`;return `<div class="side-field" draggable="true" data-detail-id="${id}"><label><span class="detail-grip" title="Drag to reorder">☰</span> ${escapeHtml(f.name)}</label><div class="side-field-control">${control}${dirty?undoButton(p.sku,id):''}</div></div>`}).join('')}</div><section class="supplier-section"><h3>Suppliers · demo data</h3><div class="notice">Multiple supplier entries will be populated from X-Series and existing Special Orders relationships when connected.</div>${[0,1].map((n)=>`<div class="supplier-row"><strong>${escapeHtml(n===0?String(value(p,'supplier')||'Primary supplier'):'Additional supplier (sample)')}</strong><small>Supplier SKU: ${escapeHtml(n===0?String(value(p,'supplierSku')||'—'):'Not linked')} · Cost: ${n===0?format(value(p,'cost'),field('cost')):'—'} · Min order: ${n===0?'1 (sample)':'—'}</small></div>`).join('')}</section><button class="full" id="expandedDescription">Open extended description editor &amp; preview</button>`;
 }else if(detailScreen==='ai'){
  const flags=[];if(!value(p,'itemOnline'))flags.push(['Online readiness','Currently not enabled online']);if(!value(p,'upc'))flags.push(['Identifier','UPC is missing']);if(Number(value(p,'cost'))===0)flags.push(['Pricing','Cost is zero']);if(!value(p,'imageSlot1'))flags.push(['Images','Primary picture is missing']);if(String(value(p,'description')||'').length<35)flags.push(['Content','Product description is short']);body=`<div class="notice"><strong>Demonstration rules only.</strong> This is not a live AI scan. No external models or APIs are called.</div><button id="scanDemo" class="full">Run checks on selected product</button><div id="scanResults">${flags.map(([type,note])=>`<div class="ai-result"><strong>${escapeHtml(type)}</strong><p>${escapeHtml(note)}</p></div>`).join('')||'<p>No example issues detected.</p>'}</div>`;
 }else{
  const cards=Array.from({length:6},(_,j)=>{const i=j+1,key='imageSlot'+i,url=String(value(p,key)||''),valid=/^https:\/\//i.test(url),dirty=Object.hasOwn(db.drafts,`${p.sku}|${key}`);return `<div class="picture-slot"><div class="picture-slot-heading"><strong>${i===1?'1 — Primary':`Position ${i}`}</strong>${dirty?undoButton(p.sku,key):''}</div><div class="picture-preview">${valid?`<img src="${escapeHtml(url)}" alt="Picture ${i}" loading="lazy" onerror="this.style.display='none'">`:'No image'}</div><label>Image URL (demo only)<input class="side-image-url" data-image-key="${key}" value="${escapeHtml(url)}" placeholder="https://example.com/image.jpg"></label><div class="picture-buttons"><button class="small" data-image-up="${i}" ${i===1?'disabled':''}>Move up</button><button class="small" data-image-down="${i}" ${i===6?'disabled':''}>Move down</button><button class="small" data-image-clear="${i}">Clear</button></div></div>`}).join('');
  body=`<div class="notice">Up to six ordered picture slots in this demo. Position 1 is primary. Changes are staged and reviewed before local demo commit. Live Lightspeed image count, upload, ordering, and Drive integration require API verification.</div><div class="picture-grid">${cards}</div><button id="driveLookup" class="full">Find matching Drive image</button>`;
 }
 $('productDetails').innerHTML=selector+body;
 $('detailScreen').onchange=e=>{detailScreen=e.target.value;details()};
 const expanded=$('expandedDescription');if(expanded)expanded.onclick=()=>descriptionEditor(p.sku);
 const scan=$('scanDemo');if(scan)scan.onclick=()=>toast('Demo rules completed — no live AI processing');
 let dragDetail=null;$('productDetails').querySelectorAll('[data-detail-id]').forEach(row=>{row.ondragstart=e=>{dragDetail=row.dataset.detailId;e.dataTransfer.setData('text/plain',dragDetail)};row.ondragover=e=>e.preventDefault();row.ondrop=e=>{e.preventDefault();const into=row.dataset.detailId;if(!dragDetail||into===dragDetail)return;const ids=[...$('productDetails').querySelectorAll('[data-detail-id]')].map(x=>x.dataset.detailId);ids.splice(ids.indexOf(dragDetail),1);ids.splice(ids.indexOf(into),0,dragDetail);profile().detailOrder=ids;save();details()}});
 $('productDetails').querySelectorAll('[data-side-key]').forEach(el=>el.onchange=()=>change(p.sku,el.dataset.sideKey,el.type==='checkbox'?el.checked:el.value));
 $('productDetails').querySelectorAll('[data-side-modal]').forEach(el=>el.onclick=()=>el.dataset.sideModal==='category'?categoryPicker(p.sku):editField(p.sku,el.dataset.sideModal));
 $('productDetails').querySelectorAll('[data-undo-key]').forEach(el=>el.onclick=()=>undoOne(el.dataset.undoSku,el.dataset.undoKey));
 $('productDetails').querySelectorAll('[data-image-key]').forEach(el=>el.onchange=()=>{if(el.value&&!/^https:\/\//i.test(el.value))return toast('Use an HTTPS image URL in the demo');change(p.sku,el.dataset.imageKey,el.value)});
 function reorder(i,j){const k='imageSlot'+i,other='imageSlot'+j,one=value(p,k),two=value(p,other);db.drafts[`${p.sku}|${k}`]=two;db.drafts[`${p.sku}|${other}`]=one;resetRedundantDrafts();save();render()}
 $('productDetails').querySelectorAll('[data-image-up]').forEach(el=>el.onclick=()=>reorder(Number(el.dataset.imageUp),Number(el.dataset.imageUp)-1));
 $('productDetails').querySelectorAll('[data-image-down]').forEach(el=>el.onclick=()=>reorder(Number(el.dataset.imageDown),Number(el.dataset.imageDown)+1));
 $('productDetails').querySelectorAll('[data-image-clear]').forEach(el=>el.onclick=()=>change(p.sku,'imageSlot'+el.dataset.imageClear,''));
 const lookup=$('driveLookup');if(lookup)lookup.onclick=()=>driveLookup(p);
}
function descriptionEditor(sku){const p=product(sku);modal('Extended Description · '+sku,`<p>Edit description below. Preview renders text safely as plain text; markup is shown literally (not executed).</p><textarea id="descriptionExpanded" rows="13" style="width:100%;min-height:210px">${escapeHtml(value(p,'description')||'')}</textarea><h3>Safe preview</h3><div id="descriptionPreview" style="white-space:pre-wrap;border:1px solid #bbc5d2;padding:12px;min-height:80px"></div>`,[{text:'Cancel',action:closeModal},{text:'Stage Description',primary:true,action:()=>{change(sku,'description',$('descriptionExpanded').value);closeModal()}}]);const edit=$('descriptionExpanded'),preview=$('descriptionPreview');const update=()=>preview.textContent=edit.value;edit.oninput=update;update()}
function modal(title,html,buttons=[]){$('modalTitle').textContent=title;$('modalBody').innerHTML=html;$('modalFoot').innerHTML='';buttons.forEach(b=>{const el=document.createElement('button');el.textContent=b.text;if(b.primary)el.className='primary';if(b.danger)el.className='danger';el.onclick=b.action;$('modalFoot').append(el)});$('overlay').classList.remove('hidden')}
function closeModal(){$('overlay').classList.add('hidden')}
let toastTimer;function toast(t){$('toast').textContent=t;$('toast').classList.remove('hidden');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.add('hidden'),3500)}
function columnsDialog(){const grouped=['X','E','HC'].map(sys=>`<h3>${sys==='X'?'X-Series':sys==='E'?'E-Series (Ecwid)':'Shared Hobby Corner Fields'}</h3><div class="fieldgrid">${fields().filter(f=>f.system===sys).map(f=>`<div class="fieldbox"><label><input type="checkbox" class="column-option" value="${f.id}" ${profile().columns.includes(f.id)?'checked':''}>${escapeHtml(f.name)}</label><small>${f.editable?'Editable':'Read-only — grey cells'}</small></div>`).join('')}</div>`).join('');modal('Choose Visible Columns',`<p class="muted">Selections belong to the current employee and layout profile. All available fields can be shown, including read-only fields.</p>${grouped}`,[{text:'Cancel',action:closeModal},{text:'Save Layout',primary:true,action:()=>{const ids=[...document.querySelectorAll('.column-option:checked')].map(e=>e.value);if(!ids.length)return toast('Choose at least one column');profile().columns=ids;save();closeModal();render()}}])}
function filtersDialog(){let temp=JSON.parse(JSON.stringify(filterRules)),mode=filterMode;function draw(){const rows=temp.map((r,i)=>`<tr><td><select class="filterField" data-i="${i}">${fields().map(f=>`<option value="${f.id}" ${r.field===f.id?'selected':''}>${escapeHtml(f.name)}</option>`).join('')}</select></td><td><select class="filterOp" data-i="${i}">${[['contains','Contains'],['notcontains','Does not contain'],['eq','Equals'],['neq','Not equal'],['empty','Is empty'],['notempty','Is not empty'],['gt','Greater than'],['lt','Less than']].map(([k,n])=>`<option value="${k}" ${k===r.op?'selected':''}>${n}</option>`).join('')}</select></td><td><input class="filterValue" data-i="${i}" value="${escapeHtml(r.value)}"></td><td><button class="small removeFilter" data-i="${i}">✕</button></td></tr>`).join('');$('modalBody').innerHTML=`<p>Combine conditions with <select id="filterMode"><option ${mode==='AND'?'selected':''}>AND</option><option ${mode==='OR'?'selected':''}>OR</option></select>. Filters are saved in this profile.</p><table class="filters-table"><tr><th>Field</th><th>Operator</th><th>Value</th><th></th></tr>${rows}</table><button id="addFilter">+ Add condition</button>`;const sync=()=>{document.querySelectorAll('.filterField').forEach(e=>temp[+e.dataset.i].field=e.value);document.querySelectorAll('.filterOp').forEach(e=>temp[+e.dataset.i].op=e.value);document.querySelectorAll('.filterValue').forEach(e=>temp[+e.dataset.i].value=e.value);mode=$('filterMode').value};$('addFilter').onclick=()=>{sync();temp.push({field:'brand',op:'contains',value:''});draw()};document.querySelectorAll('.removeFilter').forEach(b=>b.onclick=()=>{sync();temp.splice(+b.dataset.i,1);draw()});$('modalFoot').innerHTML='';[['Clear',()=>{temp=[];draw()}],['Cancel',closeModal],['Apply',()=>{sync();filterRules=temp;filterMode=mode;saveLayout();closeModal();render()}]].forEach(([label,fn])=>{const b=document.createElement('button');b.textContent=label;b.onclick=fn;if(label==='Apply')b.className='primary';$('modalFoot').append(b)})}modal('Advanced Product Filters','',[]);draw()}
function customDialog(){modal('Manage Shared Custom Fields',`<div class="notice"><strong>Administrative action.</strong> Fields and values are shared between employees. This demo has no authentication: production must enforce admin permissions on the server. Changes here affect demo data only.</div><h3>Existing fields</h3>${db.customFields.map(f=>`<div class="detail-row"><span>${escapeHtml(f.name)}</span><span class="muted">${escapeHtml(f.kind)} · ${escapeHtml(f.id)}</span></div>`).join('')}<h3>Create shared field</h3><div class="formrow"><label>Field name</label><input id="customName" maxlength="55" placeholder="e.g. Online Cleanup Note"></div><div class="formrow"><label>Field type</label><select id="customKind"><option value="text">Text / note</option><option value="number">Number / sorting</option><option value="boolean">Yes / no flag</option></select></div><p class="footnote">Internal fields are stored in the shared Hobby Corner data model. They are not automatically published to X-Series or Ecwid.</p>` ,[{text:'Cancel',action:closeModal},{text:'Create Field',primary:true,action:()=>{const name=$('customName').value.trim(),kind=$('customKind').value;if(name.length<2)return toast('Enter a descriptive field name');if(fields().some(f=>f.name.toLowerCase()===name.toLowerCase()))return toast('That field name already exists');const id='hc_'+Date.now().toString(36);db.customFields.push({id,name,kind,system:'HC',editable:true});save();closeModal();toast('Shared demo field created');render()}}])}
function bulkDialog(){if(!selected.size)return toast('Select one or more products first');const editable=fields().filter(f=>f.editable&&f.kind!=='boolean');modal('Bulk Edit Selected Products',`<p><strong>${selected.size} selected products.</strong> This stages the same value for each selected product. Existing values will be shown in the separate review window.</p><div class="formrow"><label>Field</label><select id="bulkField">${editable.map(f=>`<option value="${f.id}">${escapeHtml(f.name)} [${f.system}]</option>`).join('')}</select></div><div class="formrow"><label>New value</label><input id="bulkValue" placeholder="Value to apply"></div><div class="notice">Bulk edits never directly overwrite live records. Only the staged mock commit will change demo data.</div>` ,[{text:'Cancel',action:closeModal},{text:'Stage Bulk Change',primary:true,action:()=>{const id=$('bulkField').value,raw=$('bulkValue').value;if(raw==='')return toast('Enter a bulk value');if(field(id).kind==='number'&&(!Number.isFinite(Number(raw))||Number(raw)<0))return toast('Enter a nonnegative number');selected.forEach(sku=>{db.drafts[`${sku}|${id}`]=field(id).kind==='number'?Number(raw):raw});resetRedundantDrafts();save();closeModal();render();toast('Bulk changes staged for review')}}])}
function effectiveChanges(){return Object.entries(db.drafts).map(([k,to])=>{const [sku,id]=k.split('|'),p=product(sku),f=field(id);return p&&f?{sku,name:p.name,id,label:f.name,system:f.system,old:p[id],to}:null}).filter(Boolean).filter(c=>String(c.old??'')!==String(c.to??''))}
function reviewHtml(changes){return `<!doctype html><html><head><meta charset="utf-8"><title>Product Change Review</title><link rel="stylesheet" href="styles.css"><style>body{padding:26px;background:#f4f6fa}.review{background:white;max-width:1100px;margin:0 auto;padding:25px;border-radius:10px}.controls{display:flex;gap:10px;justify-content:flex-end;margin-top:20px}</style></head><body><div class="review"><h1>Review Product Changes</h1><p class="muted">${changes.length} field modifications · ${new Set(changes.map(c=>c.sku)).size} products · Mock data only</p><div class="notice"><strong>No live writes.</strong> “Commit Changes” updates only this browser's demonstration catalog. It will never call Lightspeed, Ecwid or Google Drive.</div><table class="changes-table"><thead><tr><th>Product</th><th>Field</th><th class="review-system">Src</th><th>Previous</th><th>Proposed</th></tr></thead><tbody>${changes.map(c=>`<tr><td><strong>${escapeHtml(c.sku)}</strong><div class="muted">${escapeHtml(c.name)}</div></td><td>${escapeHtml(c.label)}</td><td class="review-system">${escapeHtml(c.system)}</td><td class="old">${escapeHtml(c.old??'—')}</td><td class="new">${escapeHtml(c.to??'—')}</td></tr>`).join('')}</tbody></table><div class="controls"><button id="cancel">Close without committing</button><button id="commit" class="primary">Commit Changes (Demo Only)</button></div><p class="footnote">Production implementation must validate every target field, re-fetch current values, enforce permissions, prevent duplicate submissions, and log per-product outcomes.</p></div><script>document.getElementById('cancel').onclick=()=>window.close();document.getElementById('commit').onclick=()=>{if(!window.opener){alert('Original Product Manager window is unavailable. No changes committed.');return;}if(!confirm('Commit all staged changes to LOCAL DEMO DATA ONLY?'))return;window.opener.postMessage({type:'HC_DEMO_COMMIT',nonce:${JSON.stringify(reviewNonce)}},'*');window.close()};</script></body></html>`}
let reviewNonce='',reviewWindow=null;function review(){const cs=effectiveChanges();if(!cs.length)return toast('No changes to review');reviewNonce='review-'+Date.now()+'-'+Math.random().toString(36).slice(2);const popup=window.open('','hc_product_review','width=1140,height=740,scrollbars=yes,resizable=yes');if(popup){reviewWindow=popup;popup.document.open();popup.document.write(reviewHtml(cs));popup.document.close();popup.focus()}else{modal('Review Changes (Popup Blocked)',`<div class="notice">Your browser blocked the separate review window. Allow popups for this file or use the fallback below. No live data is affected.</div><div style="overflow:auto"><table class="changes-table"><tr><th>Product</th><th>Field</th><th>Old</th><th>New</th></tr>${cs.map(c=>`<tr><td>${escapeHtml(c.sku)}</td><td>${escapeHtml(c.label)}</td><td>${escapeHtml(c.old??'—')}</td><td>${escapeHtml(c.to??'—')}</td></tr>`).join('')}</table></div>`,[{text:'Cancel',action:closeModal},{text:'Commit Demo Only',primary:true,action:()=>{if(confirm('Commit to LOCAL DEMO DATA ONLY?')){commitDemo();closeModal()}}}])}}
function commitDemo(){const cs=effectiveChanges();for(const c of cs){const p=product(c.sku);if(!p||!field(c.id)?.editable)continue;p[c.id]=c.to;if(c.id==='imageSlot1')p.xImage=c.to;if(c.system==='X'){if(c.id==='price')p.ePrice=c.to;if(c.id==='description')p.eDescription=c.to}db.audit.push({at:new Date().toISOString(),user,sku:c.sku,field:c.id,old:c.old,new:c.to,mode:'DEMO_LOCAL'})}db.drafts={};save();render();toast(`Committed ${cs.length} demo field changes locally`)}
window.addEventListener('message',e=>{if(e.source!==reviewWindow||!e.data||e.data.type!=='HC_DEMO_COMMIT'||e.data.nonce!==reviewNonce)return;reviewNonce='';commitDemo()});
function driveLookup(p){const indexed=Object.entries(db.driveImages).filter(([k])=>[p.sku,p.upc,p.supplierSku].filter(Boolean).some(id=>id.toLowerCase()===k.toLowerCase()));modal('Google Drive Image Matching',`<div class="notice">This is a local matching template, not a live Google Drive search. Add an image URL indexed by SKU/UPC below to test the matching process. Real Drive access and validation require server-side integration.</div><p><strong>Identifiers:</strong> ${escapeHtml([p.sku,p.upc,p.supplierSku].filter(Boolean).join(' / '))}</p>${indexed.length?`<h3>Matched indexed images</h3>${indexed.map(([k,url])=>`<div class="fieldbox"><b>${escapeHtml(k)}</b><p>${escapeHtml(url)}</p><button class="small associate" data-key="${escapeHtml(k)}">Associate this image (demo)</button></div>`).join('')}`:'<p>No images in local index matched this product.</p>'}<h3>Add test indexed image</h3><div class="formrow"><label>Identifier</label><input id="imageCode" value="${escapeHtml(p.sku)}"></div><div class="formrow"><label>Public HTTPS image URL</label><input id="imageUrl" placeholder="https://example.com/image.jpg"></div><p class="footnote">Do not paste private Drive sharing links: authenticated Drive access will be handled by a backend, not through a public URL.</p>`,[{text:'Close',action:closeModal},{text:'Add Test Image',primary:true,action:()=>{const code=$('imageCode').value.trim(),url=$('imageUrl').value.trim();if(![p.sku,p.upc,p.supplierSku].filter(Boolean).some(id=>id.toLowerCase()===code.toLowerCase()))return toast('Identifier must match SKU, UPC or supplier item code');if(!/^https:\/\//i.test(url))return toast('Enter an HTTPS image URL');db.driveImages[code]=url;save();closeModal();driveLookup(p)}}]);document.querySelectorAll('.associate').forEach(b=>b.onclick=()=>{db.imageAssociations[p.sku]=db.driveImages[b.dataset.key];save();closeModal();details();toast('Image linked in local demo only')})}
const descriptions={
 active:'Whether this X-Series product is active. Hide inactive products with the search toolbar checkbox.',sku:'Unique item code used to identify the product in X-Series.', name:'Product name displayed in the retail catalog.',upc:'Barcode or Universal Product Code.',brand:'Manufacturer or product brand.',category:'Retail category used to organize products.',supplier:'Vendor that supplies the item.',supplierSku:'Vendor’s own item number.',cost:'What Hobby Corner pays for one unit.',price:'Regular retail selling price in X-Series.',reorder:'Minimum stock target that can trigger reordering.',restock:'Desired stock level when restocking.',inventory:'Physical quantity recorded as on hand in X-Series; read-only here.',weight:'Product weight in pounds.',dimensions:'Compact length, width and height fields in inches.',length:'Product length in inches.',width:'Product width in inches.',height:'Product height in inches.',description:'Main product description controlled by X-Series.',xImage:'Image associated with the X-Series product.',eId:'Identifier of the linked Ecwid product.',itemOnline:'X-Series Item Online Y/N setting; controls eligibility for online listing as configured.',ePrice:'Online base price synchronized from X-Series; read-only here.',eDescription:'Online base description synchronized from X-Series; read-only here.',tags:'Keywords or labels for organizing or finding products; exact X-Series mapping still needs confirmation.',variants:'Product options or variations such as color and size; summary only in this prototype.',seoTitle:'Search-engine title for the online product page; verify editable Ecwid mapping before connection.',committed:'Calculated quantity reserved for active customer holds or special orders. Demo sums unique active reservations; cannot be manually edited.',available:'On-hand quantity minus committed quantity. Can be negative if holds exceed stock.',addedBySO:'Indicates a record created through Special Orders. Source may be an existing hidden field or Railway database; mapping is not yet verified.',eMinQty:'Smallest number of this product a customer may buy in a single online order. Blank means no minimum limit.',eMaxQty:'Largest number a customer may buy in a single online order (not per customer across separate orders). Blank means no maximum limit. Variants may have their own limits.',eCompare:'Reference price displayed crossed out next to a lower online selling price (for example $49.99 next to $39.99).',eSubtitle:'Secondary online product heading or subtitle.',eLowStock:'Quantity threshold for an online low-stock warning.',eImage:'Image currently associated with the Ecwid product.'
};
function fieldDescriptions(){const details=fields().map(f=>`<div class="field-description"><strong>${escapeHtml(f.name)}</strong><span class="muted">${f.editable?'Editable':'Read-only'} · ${escapeHtml(f.system)}</span><p>${escapeHtml(descriptions[f.id]||(f.system==='HC'?'Shared internal product field; meaning is set by the store when the field is created.':'Product attribute; exact sync behavior must be verified.'))}</p></div>`).join('');return `<div class="field-description-list">${details}</div>`}
function guide(){modal('First-draft walkthrough',`<div class="stack"><p>Welcome to the PAM-style Product Manager prototype. Every feature below runs entirely in your browser and uses demonstration inventory.</p><p><strong>1.</strong> Search, sort, or filter products. Choose <b>Columns</b> to select any available X, E, or shared custom field.</p><p><strong>2.</strong> Choose an employee and one of four profiles; rename profiles and customize them independently. Browser storage persists after refresh, on this device only.</p><p><strong>3.</strong> Edit directly in the product grid. Read-only fields are grey and cannot be changed.</p><p><strong>4.</strong> Select multiple products for bulk changes. The Review Changes button opens a dedicated window showing only changes before a simulated local commit.</p><p><strong>5.</strong> Custom Fields are shared across simulated employees on this browser. The real app will use PostgreSQL and server-side permissions.</p><p><strong>6.</strong> Select a product without an image and choose Find matching Drive image to test identifier-based associations.</p><label class="guide-checkbox"><input type="checkbox" id="guideDescriptions"> Field descriptions — explain every selectable column</label><div id="guideDescriptionsBody"></div><div class="notice">Live X-Series / Ecwid API access, remote persistence, employee authentication, Google Drive search, image uploads, safe retry queues, and production commit permissions are NOT connected. No real inventory, price, or image can be modified from this prototype.</div></div>`,[{text:'Close',primary:true,action:closeModal},{text:'Reset Demo Data',danger:true,action:()=>{if(confirm('Reset ALL local demo data, drafts, and profiles?')){localStorage.removeItem(KEY);location.reload()}}}]);const checkbox=$('guideDescriptions');if(checkbox)checkbox.onchange=()=>{$('guideDescriptionsBody').innerHTML=checkbox.checked?fieldDescriptions():''}}
$('modalClose').onclick=closeModal;$('overlay').addEventListener('click',e=>{if(e.target===$('overlay'))closeModal()});$('userSelect').onchange=e=>{user=e.target.value;slot='0';setProfile()};$('profileSelect').onchange=e=>{slot=e.target.value;setProfile()};$('renameProfileBtn').onclick=()=>{const name=prompt('Name for this layout:',profile().name);if(name!==null&&name.trim()){profile().name=name.trim().slice(0,35);save();setProfile()}};$('search').oninput=e=>{search=e.target.value;render()};$('hideInactive').onchange=e=>{hideInactive=e.target.checked;saveLayout();render()};$('issuesOnly').onchange=e=>{showIssues=e.target.checked;render()};$('selectedOnly').onchange=e=>{selectedOnly=e.target.checked;render()};$('selectVisible').onchange=e=>{visible().forEach(p=>e.target.checked?selected.add(p.sku):selected.delete(p.sku));render()};$('columnsBtn').onclick=columnsDialog;$('filtersBtn').onclick=filtersDialog;$('customBtn').onclick=customDialog;$('bulkBtn').onclick=bulkDialog;$('resetWidthsBtn').onclick=()=>{if(!confirm('Reset all column widths in this layout?'))return;delete profile().widths;save();render();toast('Column widths restored')};$('reviewBtn').onclick=review;$('discardBtn').onclick=()=>{if(!draftCount())return toast('No staged changes');if(confirm('Discard all staged edits?')){db.drafts={};save();render()}};$('helpBtn').onclick=guide;document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});initProfiles();setProfile();
